  total: 99.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({ useCart: () => mockCart }));
vi.mock('./PaymentContext', () => ({ usePayment: () => mockPayment }));

describe('Checkout - The Family Operation', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockPayment.processPayment.mockResolvedValue({ orderId: 'ENZO-001' });
  });

  describe('Happy Path - A Clean Transaction', () => {
    it('completes full checkout flow like a well-run franchise', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping - we know where to deliver
      await user.type(screen.getByLabelText(/street address/i), '123 Sicily Lane');
      await user.type(screen.getByLabelText(/city/i), 'New Reno');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment - the tribute
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Uncle Enzo');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review and execute
      expect(screen.getByText(/protection services/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText(/ENZO-001/)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ENZO-001');
    });
  });

  describe('Validation - We Have Standards', () => {
    it('rejects incomplete shipping like a bad business proposal', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByRole('textbox', { name: /street/i })).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates payment credentials with Mafia precision', async () => {
      const user = userEvent.setup();
      render(<Checkout />);
      // Navigate to payment step first...
    });
  });

  describe('Error Recovery - The Family Handles Problems', () => {
    it('displays payment failure and allows retry', async () => {
      mockPayment.processPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      // ... navigate to review, attempt order

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('Edge Cases - Empty Cart', () => {
    it('redirects empty cart like unwelcome guests', () => {
      mockCart.items = [];
      render(<Checkout />);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Accessibility - We Serve Everyone', () => {
    it('meets WCAG standards', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });
  });
});
